<body>
<textarea id="tpnraw" style="display:none;position:absolute;left:-9999px">$1</textarea>

<div class="crd" id="tpncrd">
  <div class="ctop">
    <div class="cseal" id="cseal"></div>
    <div class="c-tag" id="ctag">GRACE FIELD HOUSE — CASE FILE</div>
    <div class="c-id" id="cid">— — — — —</div>
