    <div id="sk_sec"></div>
    <div id="lore_sec"></div>
    <div id="dest_sec"></div>
  </div>
  <div class="cfoot">
    <span class="cfl" id="cmotto">NEVER GIVE UP</span>
    <span class="cfr" id="cbadge">✦ TPN ✦</span>
  </div>
</div>

<script>
(function(){
function g(id){return document.getElementById(id);}
function esc(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}

/* Eye seal SVG */
function eyeSvg(){
  return '<svg viewBox="0 0 60 60" fill="none" xmlns="http://www.w3.org/2000/svg">'
   +'<circle cx="30" cy="30" r="27" stroke="#1c1408" stroke-width="1" opacity=".2"/>'
   +'<circle cx="30" cy="30" r="23" stroke="#1c1408" stroke-width=".5" stroke-dasharray="2 3" opacity=".16"/>'
   +'<path d="M10 30 Q20 15 30 15 Q40 15 50 30 Q40 45 30 45 Q20 45 10 30Z" stroke="#1c1408" stroke-width="1.2" fill="none" opacity=".65"/>'
   +'<circle cx="30" cy="30" r="8.5" stroke="#1c1408" stroke-width="1" fill="none" opacity=".8"/>'
   +'<circle cx="30" cy="30" r="4" fill="#1c1408" opacity=".75"/>'
   +'<circle cx="32.2" cy="27.8" r="1.3" fill="#f0e8d0" opacity=".55"/>'
   +'<line x1="22" y1="19" x2="20" y2="14" stroke="#1c1408" stroke-width=".7" opacity=".28"/>'
   +'<line x1="26" y1="16" x2="25" y2="11" stroke="#1c1408" stroke-width=".7" opacity=".28"/>'
   +'<line x1="30" y1="15" x2="30" y2="10" stroke="#1c1408" stroke-width=".7" opacity=".28"/>'
   +'<line x1="34" y1="16" x2="35" y2="11" stroke="#1c1408" stroke-width=".7" opacity=".28"/>'
   +'<line x1="38" y1="19" x2="40" y2="14" stroke="#1c1408" stroke-width=".7" opacity=".28"/>'
   +'</svg>';
}

/* Status color */
function statusColor(st){
  var s=(st||'').toLowerCase();
  if(/escaped|on the run/.test(s))return'#2a5c2a';
  if(/recaptured|deceased/.test(s))return'#8B1A1A';
  if(/active|in farm/.test(s))return'#5c4a28';
  if(/hiding/.test(s))return'#4a4a2a';
  return'#5c4a28';
}

/* Stat labels */
var STAT_LABELS={
  int:['Intelligence','สติปัญญา'],
  phy:['Physical','ความแข็งแกร่ง'],
  agi:['Agility','ความว่องไว'],
  wil:['Willpower','เจตจำนง'],
  team:['Teamwork','การทำงานเป็นทีม'],
  stl:['Stealth','การซ่อนตัว']
};

/* ── PARSE ── */
var raw=(g('tpnraw').value||'').replace(/<\/?TPN_CONFIRM>/gi,'').trim();
var d={};try{d=JSON.parse(raw);}catch(e){}
var TH=(d.lang==='th');

/* ── SEAL ── */
g('cseal').innerHTML=eyeSvg();

/* ── HEADER ── */
g('ctag').textContent=TH?'เกรซ ฟิลด์ เฮาส์ — แฟ้มคดี':'GRACE FIELD HOUSE — CASE FILE';
g('cid').textContent=d.id_number||'— — — — —';
g('cname').textContent=d.name||'—';

if(d.alias&&d.alias.trim()){
  g('calias').textContent='" '+d.alias+' "';
  g('calias').style.display='block';
}else{g('calias').style.display='none';}

var stEl=g('cstatus');
var stTxt=d.status||(TH?'ไม่ทราบ':'UNKNOWN');
stEl.textContent=stTxt.toUpperCase();
stEl.style.color=statusColor(stTxt);
stEl.style.borderColor=statusColor(stTxt)+'66';

/* ── QUOTE ── */
if(d.quote&&d.quote.trim()){
  g('q_sec').innerHTML='<div class="qwrap"><div class="qmark">&ldquo;</div><div class="qtext">'+esc(d.quote)+'</div></div>';
}

/* ── CHIPS ── */
var chipMap=[
  ['house','Farm','ฟาร์ม'],['role','Role','บทบาท'],
  ['alliance','Alliance','กลุ่ม'],['age','Age','อายุ'],
  ['gender','Gender','เพศ'],['rank','Rank','ลำดับ'],
  ['years_at_farm','Years','ระยะเวลา'],['fate','Fate','ชะตา']
];
var chipHtml='<div class="sep"></div><div class="crow">';
chipMap.forEach(function(cm){
  var val=d[cm[0]];
  if(val&&String(val).trim()){
    chipHtml+='<div class="chip"><span class="clbl">'+(TH?cm[2]:cm[1])+'</span>'+esc(val)+'</div>';
  }
});
chipHtml+='</div>';
g('chip_sec').innerHTML=chipHtml;

/* ── STATS ── */
if(d.stats){
  var sh='<div class="sh">'+(TH?'ผลการประเมิน':'Assessment Results')+'</div>';
  ['int','phy','agi','wil','team','stl'].forEach(function(key){
    var val=parseInt(d.stats[key])||0;
    var lb=STAT_LABELS[key];
    var nm=lb?(TH?lb[1]:lb[0]):key;
    sh+='<div class="srow">'
      +'<div class="snm">'+esc(nm)+'</div>'
      +'<div class="sdots" id="sd_'+key+'" data-val="'+val+'"></div>'
      +'<div class="sv">'+val+'</div>'
      +'</div>';
  });
  g('stat_sec').innerHTML=sh;
  ['int','phy','agi','wil','team','stl'].forEach(function(key){
    var el=g('sd_'+key);if(!el)return;
    var val=parseInt(el.getAttribute('data-val'))||0;
    for(var i=1;i<=10;i++){
      var dot=document.createElement('div');
      dot.className='sdot'+(val>=i?' on':'')+(i>=9&&val>=i?' hi':'');
      el.appendChild(dot);
    }
  });
}

/* ── SKILLS ── */
if(d.skills&&d.skills.length){
  var skH='<div class="sh">'+(TH?'ความสามารถ':'Capabilities')+'</div><div class="skrow">';
  d.skills.forEach(function(s){skH+='<div class="skitem">'+esc(s)+'</div>';});
  skH+='</div>';
  g('sk_sec').innerHTML=skH;
}

/* ── COLLAPSIBLE LORE ── */
function makeColl(id,enLabel,thLabel,content){
  if(!content||!String(content).trim())return'';
  var label=TH?thLabel:enLabel;
  return'<div class="coll" id="'+id+'">'
    +'<div class="coll-hdr" onclick="(function(){var e=document.getElementById(\''+id+'\');e.classList.toggle(\'open\');})()">'
    +esc(label)
    +'<span class="carr">▾</span></div>'
    +'<div class="coll-body"><div class="lore-blk">'+esc(content)+'</div></div>'
    +'</div>';
}
var lore='';
lore+=makeColl('cl_bg','Background','ภูมิหลัง',d.background);
lore+=makeColl('cl_app','Appearance','รูปลักษณ์',d.appearance);
lore+=makeColl('cl_per','Personality','บุคลิกภาพ',d.personality);
lore+=makeColl('cl_sec','Hidden Truth','ความจริงที่ซ่อน',d.secret);
lore+=makeColl('cl_ex','Additional Notes','หมายเหตุ',d.extra);
if(lore)g('lore_sec').innerHTML=lore;

/* ── DESTINY ROW ── */
var destHtml='';
if(d.goal||d.fate){
  destHtml+='<div class="sep"></div>';
  if(d.goal)destHtml+='<div class="drow"><span>'+(TH?'เป้าหมาย':'Goal')+'</span><span class="dval">'+esc(d.goal)+'</span></div>';
  if(d.fate)destHtml+='<div class="drow"><span>'+(TH?'ชะตากรรม':'Fate')+'</span><span class="dval red">'+esc(d.fate)+'</span></div>';
}
if(destHtml)g('dest_sec').innerHTML=destHtml;

/* ── FOOTER ── */
var motto=TH?'ไม่เคยยอมแพ้':'NEVER GIVE UP';
g('cmotto').textContent=motto;

})();
</script>
</body>
</html>

